// ─────────────────────────────────────────────────────────────
//  ۱) اعتبارسنجی آپدیت تلگرام و ساخت بدنه‌ی ارسالی به CRM
//     - پیام خودِ کانال (channel_post) مشتری نیست و رد می‌شود
//     - پیام ربات‌ها رد می‌شود
// ─────────────────────────────────────────────────────────────
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const body = (j.body && typeof j.body === 'object') ? j.body : j;

  if (body.update_id === undefined || body.update_id === null) {
    out.push({ json: { isCustomerMessage: false, skipReason: 'update_id ندارد', update_id: null } });
    continue;
  }

  const msg = body.message || body.edited_message || null;
  const isChannelBroadcast = !!body.channel_post && !body.message;

  let from = null, chat = null, text = '', msgId = null, phone = null, isBot = false;
  if (msg) {
    from = msg.from || null;
    chat = msg.chat || null;
    text = msg.text || msg.caption || '';
    msgId = msg.message_id;
    isBot = !!(from && from.is_bot);
    if (msg.contact && msg.contact.phone_number) phone = msg.contact.phone_number;
    if (!text) {
      if (msg.photo) text = '[عکس]';
      else if (msg.voice) text = '[ویس]';
      else if (msg.document) text = '[فایل]';
      else if (msg.sticker) text = '[استیکر]';
      else text = '[پیام]';
    }
  }

  const isCustomerMessage = !!msg && !!from && !isBot && !isChannelBroadcast && String(text).trim().length > 0;
  let skipReason = null;
  if (!isCustomerMessage) {
    if (isChannelBroadcast) skipReason = 'پست خودِ کانال است، مشتری نیست';
    else if (isBot) skipReason = 'فرستنده ربات است';
    else if (!msg) skipReason = 'این نوع آپدیت پیام ندارد';
    else skipReason = 'پیام قابل پردازش نیست';
  }

  out.push({ json: {
    isCustomerMessage,
    skipReason,
    update_id: String(body.update_id),
    chatId: chat ? String(chat.id) : (from ? String(from.id) : null),
    externalId: from ? String(from.id) : null,
    username: (from && from.username) ? from.username : null,
    name: from ? [from.first_name, from.last_name].filter(Boolean).join(' ') : null,
    text: String(text),
    phoneFromContact: phone,
    messageId: msgId ? String(msgId) : null,
    // بدنه‌ی دست‌نخورده‌ی تلگرام برای فوروارد به CRM
    crmPayload: body,
  }});
}
return out;

// ─────────────────────────────────────────────────────────────
//  ۲) خواندن پاسخ وبهوک CRM و تشخیص نیت خرید
//     کلیدواژه‌ها دقیقاً همان‌هایی هستند که خود CRM چک می‌کند
// ─────────────────────────────────────────────────────────────
const out = [];
for (const item of $input.all()) {
  const res = item.json || {};
  const statusCode = res.statusCode || 0;

  let payload = res.body;
  if (typeof payload === 'string') { try { payload = JSON.parse(payload); } catch (e) { payload = {}; } }
  payload = payload || {};

  const src = $('Normalize').first().json;
  const t = String(src.text || '').toLowerCase();

  const intentPrice   = t.includes('قیمت') || t.includes('price') || t.includes('هزینه');
  const intentStock   = t.includes('موجود') || t.includes('stock') || t.includes('موجودی');
  const intentProduct = t.includes('محصول') || t.includes('خرید') || t.includes('سفارش') || t.includes('product');
  const hot = intentPrice || intentStock || intentProduct;

  const hasCustomer = !!payload.customerId;
  const isDup = payload.duplicate === true;
  out.push({ json: {
    statusCode,
    // موفق = ۲۰۰/۲۰۱ «و» (مشتری ساخته شده یا آپدیت تکراری است)
    ok: (statusCode === 200 || statusCode === 201) && (hasCustomer || isDup),
    duplicate: isDup,
    received: payload.received === true,
    customerId: payload.customerId || null,
    messageId: payload.messageId || null,
    leadId: payload.leadId || null,
    crmError: payload.error || null,

    text: src.text,
    chatId: src.chatId,
    name: src.name,
    username: src.username,
    phoneFromContact: src.phoneFromContact,
    intent: { price: intentPrice, stock: intentStock, product: intentProduct },
    hot,
    tag: intentPrice ? 'استعلام قیمت'
       : intentStock ? 'استعلام موجودی'
       : intentProduct ? 'علاقه‌مند به خرید'
       : 'پیام ورودی',
  }});
}
return out;

// ─────────────────────────────────────────────────────────────
//  ۳) گرفتن توکن JWT برای بقیه‌ی درخواست‌ها
// ─────────────────────────────────────────────────────────────
const out = [];
for (const item of $input.all()) {
  const res = item.json || {};
  let payload = res.body;
  if (typeof payload === 'string') { try { payload = JSON.parse(payload); } catch (e) { payload = {}; } }
  payload = payload || (res.token ? res : {});
  const crm = $('Read CRM Result').first().json;

  out.push({ json: {
    ...crm,
    token: payload.token || null,
    role: payload.role || null,
    loginStatus: res.statusCode || 200,
    loginOk: !!payload.token,
  }});
}
return out;

// ─────────────────────────────────────────────────────────────
//  ۴) پیدا کردن پاسخِ ساخته‌شده توسط ایجنت داخلی CRM
//     ایجنت CRM پاسخ را به‌صورت پیام OUTBOUND با metadata.via = 'agent' ذخیره می‌کند
//     ولی آن را به تلگرام نمی‌فرستد — کارِ این ورک‌فلو همین است.
// ─────────────────────────────────────────────────────────────
const out = [];
for (const item of $input.all()) {
  const res = item.json || {};
  let payload = res.body;
  if (typeof payload === 'string') { try { payload = JSON.parse(payload); } catch (e) { payload = {}; } }
  payload = payload || {};

  const crm = $('Read CRM Result').first().json;
  const login = $('Read Login').first().json;

  const list = Array.isArray(payload.messages) ? payload.messages : [];
  const inboundId = crm.messageId;
  // پیام‌ها از جدید به قدیم مرتب‌اند
  const agentMsg = list.find(m =>
      m && m.direction === 'OUTBOUND' &&
      ((m.metadata && m.metadata.via === 'agent') || (m.metadata && m.metadata.intent))
  );
  const newest = list.length ? list[0] : null;
  const reply = agentMsg ? String(agentMsg.content || agentMsg.text || '').trim() : '';

  out.push({ json: {
    ...crm,
    token: login.token,
    messagesSeen: list.length,
    agentReplyId: agentMsg ? agentMsg.id : null,
    reply,
    hasReply: reply.length > 0,
    newestDirection: newest ? newest.direction : null,
    fetchStatus: res.statusCode || 0,
  }});
}
return out;
